public class DateTimeZone_forOffsetHoursMinutes_TriageGen2Test {

    @Test
    public void testForOffsetHoursMinutes_UTC() {
        DateTimeZone zone = DateTimeZone.forOffsetHoursMinutes(0, 0);
        assertEquals(DateTimeZone.UTC, zone);
    }

    @Test
    public void testForOffsetHoursMinutes_PositiveOffset() {
        // Test +5:30
        DateTimeZone zone = DateTimeZone.forOffsetHoursMinutes(5, 30);
        int expectedOffset = (5 * 60 + 30) * DateTimeConstants.MILLIS_PER_MINUTE;
        assertEquals(expectedOffset, zone.getOffset(0));
    }

    @Test
    public void testForOffsetHoursMinutes_NegativeOffset() {
        // Test -5:30
        // Logic: hoursInMinutes = -300. minutesOffset = -300 - 30 = -330.
        // offset = -330 * 60000 = -19800000
        DateTimeZone zone = DateTimeZone.forOffsetHoursMinutes(-5, 30);
        int expectedOffset = ((-5 * 60) - 30) * DateTimeConstants.MILLIS_PER_MINUTE;
        assertEquals(expectedOffset, zone.getOffset(0));
    }

    @Test
    public void testForOffsetHoursMinutes_BoundaryPositive() {
        // Max valid hours: 23, Max valid minutes: 59
        DateTimeZone zone = DateTimeZone.forOffsetHoursMinutes(23, 59);
        int expectedOffset = (23 * 60 + 59) * DateTimeConstants.MILLIS_PER_MINUTE;
        assertEquals(expectedOffset, zone.getOffset(0));
    }

    @Test
    public void testForOffsetHoursMinutes_BoundaryNegative() {
        // Min valid hours: -23, Max valid minutes: 59
        DateTimeZone zone = DateTimeZone.forOffsetHoursMinutes(-23, 59);
        int expectedOffset = ((-23 * 60) - 59) * DateTimeConstants.MILLIS_PER_MINUTE;
        assertEquals(expectedOffset, zone.getOffset(0));
    }

    @Test(expected = IllegalArgumentException.class)
    public void testForOffsetHoursMinutes_HoursTooHigh() {
        DateTimeZone.forOffsetHoursMinutes(24, 0);
    }

    @Test(expected = IllegalArgumentException.class)
    public void testForOffsetHoursMinutes_HoursTooLow() {
        DateTimeZone.forOffsetHoursMinutes(-24, 0);
    }

    @Test(expected = IllegalArgumentException.class)
    public void testForOffsetHoursMinutes_MinutesTooHigh() {
        DateTimeZone.forOffsetHoursMinutes(5, 60);
    }

    @Test(expected = IllegalArgumentException.class)
    public void testForOffsetHoursMinutes_MinutesTooLow() {
        DateTimeZone.forOffsetHoursMinutes(5, -1);
    }

    /**
     * To trigger ArithmeticException in FieldUtils.safeMultiply, 
     * we need the total minutes to be extremely large.
     * However, the input validation for hours (-23 to 23) and minutes (0 to 59)
     * limits the maximum possible offset to ~1419 minutes.
     * 1419 * 60,000 = 85,140,000, which fits easily in an integer.
     * 
     * Under normal constraints of the 'if' checks, ArithmeticException is unreachable.
     * But for branch coverage of the catch block in a triage scenario, 
     * if we assume the validation logic were bypassed or modified, we'd test it.
     * Given the current code provided, the validation prevents the overflow.
     */
}
